import { apiv2Base, apiv2ServerHeaders } from "@/services/apiv2";

// Tur kategori sayfası cache cron'uyla (apiv3 RefreshTourCategoryPageCache) birebir
// aynı agregasyon isteği — canlı sayfalarda (deals/search) filtre sayaçlarını üretmek
// için apiv2 search'e gönderilir. apiv2 agregasyonu yalnızca request ile hesaplar.
const AGGREGATION_PARAMS = {
    aggregation: ["defaults.regular", "defaults.private", "languages.id.keyword"],
    multiagg: ["category.name.en.keyword;category.slug.keyword:category.id"],
    aggraw: {
        activities_name_en_keyword: {
            terms: { field: "activities.name.en.keyword", size: 10000 },
            aggs: {
                activities_sid_keyword: {
                    terms: { field: "activities.sid.keyword", size: 1 },
                    aggs: {
                        activities_category_id: {
                            terms: { field: "activities.category_id", size: 1 },
                        },
                    },
                },
            },
        },
        accommodation_types_sid_keyword: {
            terms: { field: "accommodation_types.sid.keyword", size: 10000 },
            aggs: {
                accommodation_types_name_en_keyword: {
                    terms: { field: "accommodation_types.name.en.keyword", size: 1 },
                },
            },
        },
        guide_type_sid_keyword: {
            terms: { field: "guide_type.sid.keyword", size: 10000 },
            aggs: {
                guide_type_name_keyword: {
                    terms: { field: "guide_type.name.en.keyword", size: 1 },
                },
            },
        },
    },
};

const mapBuckets = (aggs: any, key: string) =>
    (aggs?.[key]?.buckets ?? []).map((b: any) => ({
        keyName: b.key,
        tourCount: b.doc_count ?? 0,
    }));

const mapActivities = (aggs: any) => {
    const buckets = aggs?.activities_name_en_keyword?.buckets ?? [];
    const out: any[] = [];
    for (const a of buckets) {
        const sid = a.activities_sid_keyword?.buckets?.[0];
        if (!sid) continue;
        out.push({
            keyName: sid.key,
            categoryId: sid.activities_category_id?.buckets?.[0]?.key ?? null,
            tourCount: a.doc_count ?? 0,
        });
    }
    return out;
};

const mapServiceTypes = (aggs: any) => {
    const out: any[] = [];
    const pairs: [string, string][] = [
        ["regular", "defaults_regular"],
        ["private", "defaults_private"],
    ];
    for (const [name, key] of pairs) {
        const bucket = (aggs?.[key]?.buckets ?? []).find(
            (b: any) => b.key === 1 || b.key_as_string === "true"
        );
        const count = bucket?.doc_count ?? 0;
        if (count > 0) out.push({ keyName: name, tourCount: count });
    }
    return out;
};

// ES aggregations → modalın beklediği `filters` yapısı (cache transform'uyla birebir).
function buildFiltersFromAggregations(aggs: any) {
    const filters: any = {
        accommodationTypes: mapBuckets(aggs, "accommodation_types_sid_keyword"),
        activities: mapActivities(aggs),
        serviceTypes: mapServiceTypes(aggs),
        guideTypes: mapBuckets(aggs, "guide_type_sid_keyword"),
        languages: mapBuckets(aggs, "languages_id_keyword"),
    };
    Object.keys(filters).forEach((k) => {
        if (!filters[k] || filters[k].length === 0) delete filters[k];
    });
    return filters;
}

export default async function getData({ page, filterData, currency, aggregations = false }: { page: number; filterData: any; currency: any; aggregations?: boolean; }) {
    // Display-only labels (şehir adları) apiv2 search gövdesine gitmesin.
    const { start_location_name, end_location_name, ...filters } = filterData ?? {};

    var requestBody = {
        activeCurrency: currency,
        page,
        page_size: 20,
        ...filters,
        ...(aggregations ? AGGREGATION_PARAMS : {}),
    };

    const res = await fetch(
        `${apiv2Base()}/b2c/tours/search`,
        {
            cache: "force-cache",
            method: "POST",
            headers: {
                ...apiv2ServerHeaders(),
                "Content-type": "application/json",
                "Content-Language": "en",
                "Accept": "*/*",
                "Accept-Encoding": "gzip, deflate, br",
                "Origin": "https://travelshopbooking.com",
            },
            body: JSON.stringify(requestBody),
        }
    );

    if (!res.ok)
        throw new Error("Failed to fetch data");

    const json = await res.json();

    // Canlı sayfalarda (deals/search) filtre sayaçlarını agregasyonlardan üret.
    if (aggregations) json.filters = buildFiltersFromAggregations(json.aggregations ?? {});

    return json;
}
